def gf8_mult(a, b):
    p = 0
    for i in range(3):
        if (b & (1 << i)):
            p ^= (a << i)
    # reduce modulo x^3 + x + 1 (which is 1011 in binary, i.e., 11)
    if p & 16:
        p ^= (11 << 1)
    if p & 8:
        p ^= 11
    return p

X = []
Y = []
for i in range(8):
    for j in range(8):
        X.append(i ^ j)
        Y.append(i ^ gf8_mult(2, j))

# Verify Latin square property
def is_latin(sq):
    for i in range(8):
        row = sq[i*8:(i+1)*8]
        col = [sq[k*8+i] for k in range(8)]
        if len(set(row)) != 8 or len(set(col)) != 8:
            return False
    return True

print("X is Latin:", is_latin(X))
print("Y is Latin:", is_latin(Y))

# Verify orthogonality
pairs = set(zip(X, Y))
print("Orthogonal:", len(pairs) == 64)

print("X =", X)
